********************************************************************************** Global equates*********************************************************************************** Constants*Version	equ $0300	;Version numbernil	equ 0	;Nil pointer valuetrue	equ $FFFF	;Boolean truefalse	equ $0000	;Boolean false* OwnerIDsBusyID	equ $0000	;Non existent ramRDiskID	equ $0001	;Ram disk memorySaveID	equ $00FF	;Used to save through hard resetHandleID	equ $F0FF	;ID number for creating handles** Bank E1 memory equates* addresses $E115FE	- $E11AFF are reserved for the memory manager* addresses $E11680	- $E116FF is used by ramdisk*MMRam	equ $E115FE	;Beginning of our ramMMRamEnd	equ $E11AFF	;Last byte of our ram* Power up flag set	by monitorPowerFlag	equ $E115FE	;High byte set to 0	by monitor* Pointers to segment listsMemList	equ $E11600	;List of used segmentsPurgeList	equ $E11604	;List of used but empty handlesFreeList	equ $E11608	;List of free handlesMem01	equ $E1160C	;Beginning of bank 1Mem02	equ $E11610	;Beginning of bank 2MemE0	equ $E11614	;Beginning of bank E0MemE1	equ $E11618	;Beginning of bank E1MemFF	equ $E1161C	;Last segmentGHSize	equ $E11620	;Handle Size global* Other stuffNumBanks	equ $E11624	;Number of 64K banks in machine;-----------------------------------------------------------;; New Equates added by Steve Glass;; 29 Aug 88;LastLowHandle	equ $E11628LastHighHandle	equ $E1162CNewHandleCount	equ $E11630ShortCutCount	equ $E11634FirstOOMPtr	equ $E11638NewDebugLoc	equ $FEFFFCDisposeDebugLoc	equ $FEFFF8;-----------------------------------------------------------* RamDisk equatesBlockSize	equ $E11640	;Maximim size in blocks (word)CurDiskSize	equ $E11642	;Current disk size in bytesDiskHandles	equ $E11646	;Pointer to disk handlesFormatFlag	equ $E1164A	;Flag if formattedPendingSysBeep2	equ $E1167E	;one word for SysBeep2/GetNextEvent (17-Sep-91 DAL)* These are patchable vectors to low level routinesMMPatcher	equ $E11680	;Call to relink ram	based MMWarmStart	equ $E11684Link	equ $E11688CleanUp	equ $E1168CSearch	equ $E11690CheckFit	equ $E11694Realloc	equ $E11698GetFree	equ $E1169CCreateHandles	equ $E116A0MoveData	equ $E116A4SearchFail	equ $E116A8Compact	equ $E116ACPurge	equ $E116B0UserPurge	equ $E116B4Restart	equ $E116B8VLen	equ 4*15-2	;# bytes of vectorsHandleBuf	equ $E11700	;$E11700 - $E1AFF is used for handles* Other $E1 equatesIncBusyFlg	equ $E10064	;Semaphore for schedulerDecBusyFlg	equ $E10068	;Resets semaphoreIrqActive	equ $E100CB	;Byte <> 0 if in interrupt* Battery ram equatesMinDiskParm	equ $E102F6	;Minimum disk parm in battery ramMaxDiskParm	equ $E102F7	;Maximum disk parm $0-$10** Zero page stuff*error	equ 1	;Error codeaddr	equ error+2Source	equ addrattr	equ addr+4Dest	equ attr	;Block Move Destinationowner	equ attr+2size	equ owner+2Count	equ sizehndl1	equ size+4hndl2	equ hndl1+4TempCount	equ hndl2	;Can't be handle1 for compacthndl	equ hndl2+4addr1	equ hndl+4addr2	equ addr1+4Retry	equ addr2+4ZPSize	equ Retry+2-1	;# bytes we're adding to stacknumparms	equ Retry+2return	equ numparms+2	;Users 2 return addressesparms	equ return+6	;Parameters start here* Parameters and function resultsParmHndl	equ parms	;Inputted handle for most callsResHndl	equ parms+12	;Handle returned by	newhandle;		 and handle inputted by reallochandle* End of zero page stuff** The handle data structure*Hndl_Addr	equ 0	;4 byte address pointed to by handleHndl_Attr	equ 4	;2 byte attributes byteHndl_Owner	equ 6	;2 byte segment owner IDHndl_Size	equ 8	;4 byte sizeHndl_Prev	equ 12	;4 byte pointer to previous handleHndl_Next	equ 16	;4 byte pointer to next handleHSize	equ 20	;Size of handle data structure* Handle attributes	bitsAttr_Locked	equ $8000	;1 = LockedAttr_Fixed	equ $4000	;1 = Not movableAttr_System	equ $2000	;1 = System handleAttr_Handle	equ $1000	;1 = block of handlesAttr_Purge	equ $0300	;0 = No purge 1-3 purge levelAttr_NoCross	equ $0010	;1 = May not cross banksAttr_NoSpec	equ $0008	;1 = May not use special memoryAttr_Page	equ $0004	;1 = Page AlignedAttr_Addr	equ $0002	;1 = Fixed addressAttr_Bank	equ $0001	;1 = Fixed bank** Error codes*MFullErr	equ $0201	;Memory full errorNilErr	equ $0202	;Operation on a nil	handleNotNilErr	equ $0203	;Operation on a non	nil handleLockErr	equ $0204	;Operation on a locked blockPurgeErr	equ $0205	;Attempt to purge unpurgeable blockHandleErr	equ $0206	;Invalid handle inputtedIDErr	equ $0207	;Invalid ownerAttrErr	equ $0208	;Invalid attributesOOMQueueDamaged	equ $0209	;The queue of out of memory routines is damagedQueueSignature	equ $A55A;=================================================;; Equates for the protocal converter.;* Zero page equates.  These are in real	zero page!!!PCBuffer	equ $42	;Three bytes of buffer pointerPCCommand	equ $45	;Protocol converter	commandPCBufferH	equ $47	;4th byte of buffer	pointerPCBlockNum	equ $48	;Block numberPCStatCode	equ $48	;Status/Control codePCStatByte	equ $50	;Error codePCXferCount	equ $51	;Bytes transferred countProFlag	equ $00BF00	;<> 0 for ProDOS* Error codesPCBadCmd	equ $01	;Bad command numberPCBadCtl	equ $21	;Bad Ctl or Status codePCIOErr	equ $27	;I/O errorPCNoDrive	equ $28	;No device errorPCBadBlk	equ $2D	;Bad Block numberDIBLen	equ 21	;Length of DIB